package ru.bububu.radio.sources;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public final class PortableSourceParserTest {
    @Test public void exactUnicodeWhitespaceIncludesNbspNelButNotFormatCharacters()throws Exception{List<Integer> spaces=new ArrayList<>();for(int c=9;c<=13;c++)spaces.add(c);spaces.addAll(List.of(0x20,0x85,0xa0,0x1680,0x2028,0x2029,0x202f,0x205f,0x3000));for(int c=0x2000;c<=0x200a;c++)spaces.add(c);for(int c:spaces)assertEquals(Integer.toHexString(c),"аб",SourceSemantic45.fold("а"+(char)c+"б"));for(int c:List.of(0x180e,0x200b,0xfeff))assertEquals("а"+(char)c+"б",SourceSemantic45.fold("а"+(char)c+"б"));assertEquals("а б",SourceSemantic45.fragment("<p>а\u00a0\u0085\u2007б</p>",new RequestScope(1,1)));}
    @Test public void secureRssAcceptsCdataAndRejectsDtdEntities()throws Exception{String valid="<rss version='2.0'><channel><title>Наука</title><item><title><![CDATA[Текст & подробности]]></title></item></channel></rss>";assertNotNull(ClosedRss45.parse(response(valid),new RequestScope(1,1)));for(String dtd:List.of("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///PRIVATE'>]>","<!DOCTYPE rss SYSTEM 'https://invalid.invalid/PRIVATE'>","<!DOCTYPE rss [<!ENTITY x 'expanded'>]>")){SourceFailure f=assertThrows(SourceFailure.class,()->ClosedRss45.parse(response(dtd+"<rss>&x;</rss>"),new RequestScope(1,1)));assertEquals("XML_DTD",f.reason);}}
    @Test public void compactDiagnosticsContainCauseAndPublicRouteNeverQueryOrUserPath(){LoadFailureSnapshot d=new LoadFailureSnapshot(SourceClock.SYSTEM,1);SourceRecord s=SourceProfiles45.six().get(0).seed();d.context(s);d.response(503,"text/html",s.url+"?SECRET_QUERY=PRIVATE");d.failure(new SourceFailure("XML_FORMAT",new org.xml.sax.SAXNotRecognizedException("PRIVATE MESSAGE")));String json=d.json(SourceFailureInfo.forReason("XML_FORMAT"));assertTrue(json.contains("SAXNotRecognizedException"));assertTrue(json.contains("\"received_http_status\":503"));assertFalse(json.contains("PRIVATE"));assertFalse(json.contains("SECRET_QUERY"));SourceRecord user=SourceRecord.create("rss","https://example.org/private","Личная станция","https://example.org/private","rss",false);d.context(user);d.response(200,"text/xml","https://example.org/SECRET_PATH?TOKEN=SECRET");assertFalse(d.json(SourceFailureInfo.forReason("XML_FORMAT")).contains("SECRET"));}
    private static SourceTransport.Response response(String xml){return new SourceTransport.Response(xml.getBytes(StandardCharsets.UTF_8),"https://example.org/rss",200,"text/xml","UTF-8",null,null);}
}
